from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
def put(slug,text):(ROOT/'apps'/slug/'tests/activity.test.ts').write_text(text,encoding='utf-8')
put('quranic-places-atlas','''import {test,expect} from 'bun:test';import {places,landPaths} from '../src/data/content.json';
test('fifteen entries have unique routes, complete text, and commentary',()=>{expect(places).toHaveLength(15);expect(new Set(places.map(p=>p.id)).size).toBe(15);for(const p of places){expect(p.passage.arabic.length).toBeGreaterThan(0);expect(p.passage.translation.length).toBeGreaterThan(0);expect(p.commentaryUrl).toMatch(/^https:\\/\\/quran.com\\//);expect(p.note.length).toBeGreaterThan(30);}});
test('only five contextual coordinates are assigned and each has a primary geography source',()=>{const mapped=places.filter(p=>p.point);expect(mapped).toHaveLength(5);for(const p of mapped){expect(p.point![0]).toBeGreaterThan(20);expect(p.point![0]).toBeLessThan(60);expect(p.point![1]).toBeGreaterThan(10);expect(p.point![1]).toBeLessThan(42);expect(['ungegn.un.org','whc.unesco.org']).toContain(new URL(p.geoUrl).hostname);}for(const p of places.filter(p=>!p.point))expect(p.geoUrl).toBe('');});
test('unresolved identifications remain unpinned',()=>{for(const id of ['iram','tuwa','al-judi','al-ahqaf','midian'])expect(places.find(p=>p.id===id)!.point).toBeNull();});
test('map geometry is bundled finite SVG path data',()=>{expect(landPaths.length).toBeGreaterThan(10);expect(landPaths.every(d=>/^M[-\\d.,L]+Z$/.test(d)&&!d.includes('NaN'))).toBe(true);});
''')
put('islamic-concept-connections','''import {test,expect} from 'bun:test';import {groups,puzzles} from '../src/data/content.json';import {match,valid} from '../src/lib/engine';
test('sixteen boards contain four groups and sixteen distinct terms',()=>{expect(puzzles).toHaveLength(16);for(const p of puzzles){expect(new Set(p.groups).size).toBe(4);const terms=p.groups.flatMap(id=>groups.find(g=>g.id===id)!.terms);expect(terms).toHaveLength(16);expect(new Set(terms).size).toBe(16);}});
test('every group has four distinct terms and complete source readings',()=>{for(const g of groups){expect(new Set(g.terms).size).toBe(4);expect(g.passages.length).toBeGreaterThan(0);expect(g.passages.every(p=>p.arabic&&p.translation&&p.translationUrl)).toBe(true);}});
test('matching requires all and only four unique terms',()=>{const g=groups[0]!;expect(match([...g.terms].reverse(),groups).group).toBe(g.id);expect(match([...g.terms.slice(0,3),'unrelated'],[g]).near).toBe(true);expect(match([g.terms[0]!,g.terms[0]!,g.terms[0]!,g.terms[0]!],groups).group).toBeNull();expect(match(g.terms.slice(0,3),groups).group).toBeNull();});
test('progress cannot inject solved groups from another board or corrupt counters',()=>{const p={puzzle:puzzles[0]!.id,solved:[],hints:[],misses:0,seed:'sample',revealed:false};expect(valid(p,puzzles)).toBe(true);expect(valid({...p,solved:['absent']},puzzles)).toBe(false);expect(valid({...p,misses:-1},puzzles)).toBe(false);expect(valid({...p,seed:'<script>'},puzzles)).toBe(false);});
''')
put('islamic-history-timeline-challenge','''import {test,expect} from 'bun:test';import {packs,events} from '../src/data/content.json';import {grade,permutation,valid} from '../src/lib/engine';
test('twelve challenges each refer to four distinct source-backed events in broad chronology',()=>{expect(packs).toHaveLength(12);for(const p of packs){expect(new Set(p.events).size).toBe(4);const rows=p.events.map(id=>events.find(e=>e.id===id)!);expect(rows.map(r=>r.year)).toEqual([...rows.map(r=>r.year)].sort((a,b)=>a-b));expect(rows.every(r=>r.sources.length>0&&r.uncertainty.length>0)).toBe(true);}});
test('grading counts correct positions and inverted pairs',()=>{expect(grade(['a','b','c','d'],['a','b','c','d'])).toEqual({correct:true,positions:[true,true,true,true],inversions:0});expect(grade(['d','c','b','a'],['a','b','c','d']).inversions).toBe(6);expect(grade(['a','c','b','d'],['a','b','c','d']).positions).toEqual([true,false,false,true]);});
test('event permutations cannot contain duplicates, omissions, or foreign IDs',()=>{expect(permutation(['a','a'],['a','b'])).toBe(false);expect(permutation(['b'],['a','b'])).toBe(false);expect(()=>grade(['a','x'],['a','b'])).toThrow();});
test('a stored complete state must have the correct order',()=>{const pack=packs[0]!;const p={pack:pack.id,order:pack.events,tries:1,hint:false,revealed:false,complete:true,seed:'seed'};expect(valid(p,packs)).toBe(true);expect(valid({...p,order:[...pack.events].reverse()},packs)).toBe(false);expect(valid({...p,tries:NaN},packs)).toBe(false);});
''')
put('understand-salah-lab','''import {test,expect} from 'bun:test';import {lessons,audio} from '../src/data/content.json';import provenance from '../src/data/provenance.json';import {readFileSync} from 'node:fs';import {createHash} from 'node:crypto';
test('fifteen lessons provide seven complete canonical ayahs and eight cited recitations',()=>{expect(lessons).toHaveLength(15);expect(new Set(lessons.map(l=>l.id)).size).toBe(15);expect(lessons.filter(l=>l.passage)).toHaveLength(7);expect(lessons.filter(l=>!l.passage)).toHaveLength(8);for(const l of lessons){if(l.passage){expect(l.arabic).toBe(l.passage.arabic);expect(l.meaning).toBe(l.passage.translation);expect(l.commentaryUrl).toMatch(/^https:\\/\\/quran.com\\//);}else expect(l.sources.length).toBeGreaterThan(0);}});
test('every comprehension question has four options and one intended answer',()=>{for(const l of lessons){expect(new Set(l.options).size).toBe(4);expect(l.answer).toBeGreaterThanOrEqual(0);expect(l.answer).toBeLessThan(4);}});
test('local audio has its recorded hash and explicit reuse attribution',()=>{const bytes=readFileSync(new URL('../public/audio/fatiha.mp3',import.meta.url));expect(bytes.length).toBeGreaterThan(100000);expect(createHash('sha256').update(bytes).digest('hex')).toBe(provenance.audioSha256);expect(audio.license).toBe('CC BY-SA 4.0');expect(audio.file).toBe('/audio/fatiha.mp3');const notice=readFileSync(new URL('../public/audio/ATTRIBUTION.txt',import.meta.url),'utf8');expect(notice).toContain('Adeel Shaikh');expect(notice).toContain('https://creativecommons.org/licenses/by-sa/4.0/');});
test('audio availability is limited to the whole-surah Al-Fatiha lessons',()=>{expect(lessons.filter(l=>l.audio)).toHaveLength(7);expect(lessons.filter(l=>l.audio).every(l=>l.area==='Al-Fatiha'&&l.note.includes('whole surah'))).toBe(true);});
''')
put('quranic-parables-studio','''import {test,expect} from 'bun:test';import {parables} from '../src/data/content.json';
test('fourteen unique readings have three named diagram parts and full source text',()=>{expect(parables).toHaveLength(14);expect(new Set(parables.map(p=>p.id)).size).toBe(14);for(const p of parables){expect(p.nodes).toHaveLength(3);expect(p.nodes.every(n=>n.label&&n.detail)).toBe(true);expect(p.passage.arabic.length).toBeGreaterThan(0);expect(p.passage.translationUrl).toMatch(/^https:\\/\\/quran.com\\//);}});
test('each reading check has distinct answers and a valid intended answer',()=>{for(const p of parables){expect(new Set(p.options).size).toBe(4);expect(p.answer).toBeGreaterThanOrEqual(0);expect(p.answer).toBeLessThan(4);expect(p.commentaryUrl).toContain('/tafsirs/16');}});
test('the Light reading cites the actual second commentary edition',()=>{expect(parables.find(p=>p.id==='lamp')!.secondCommentaryUrl).toBe('https://quran.com/24:35/tafsirs/926');});
test('the two-gardens reading retains all thirteen ayahs',()=>{const p=parables.find(p=>p.id==='two-gardens')!;expect(p.passage.ref).toBe('18:32-44');expect(p.passage.arabic.split('\\n')).toHaveLength(13);expect(p.passage.translation.split('\\n')).toHaveLength(13);});
''')
